import React from "react";
import InputItem from "./inputitems"; // Adjust the import path as necessary

const Step5 = ({ userObject, handleProjectChange, addProject, removeProject }) => {
    return (
        <div>
            <h2>Projects</h2>
            {(userObject.projects || []).map((project, index) => (
                <div key={index} className="project-item">
                    <InputItem
                        type="text"
                        placeholder="Project Title"
                        value={project.title}
                        onChange={(e) => handleProjectChange(index, "title", e.target.value)}
                    />
                                        {exp.description.map((desc, descIndex) => (
                        <div key={descIndex} className='description-item'>
                            <InputItem
                                className='description'
                                onChange={(e) => handleDescriptionChange(index, descIndex, e.target.value)}
                                label={`Description ${descIndex + 1}`}
                                placeholder='Enter job description'
                                name={`description-${index}-${descIndex}`}
                                value={desc}
                            />
                            <button type='button' className='rbutton' onClick={() => removeDescription(index, descIndex)}>Remove Description</button>
                        </div>
                    ))}
                    <InputItem
                        type="text"
                        placeholder="Technologies Used"
                        value={project.technologies}
                        onChange={(e) => handleProjectChange(index, "technologies", e.target.value)}
                    />
                    <InputItem
                        type="text"
                        placeholder="Project Link (Optional)"
                        value={project.link}
                        onChange={(e) => handleProjectChange(index, "link", e.target.value)}
                    />
                    <button onClick={() => removeProject(index)}>Remove</button>
                </div>
            ))}
            <button onClick={addProject}>Add Project</button>
        </div>
    );
};

export default Step5;
